const DEFAULT_MERMAID_PREFERENCES = {
  theme: "auto",
  look: "classic",
  layout: "dagre"
};
function resolveMermaidTheme(pref, appMode) {
  if (pref !== "auto") return pref;
  return appMode === "dark" ? "dark" : "default";
}
function renderOptionsKey(opts) {
  return `${opts.theme}|${opts.look}|${opts.layout}|${opts.pieLegend ?? "right"}`;
}
export {
  DEFAULT_MERMAID_PREFERENCES,
  renderOptionsKey,
  resolveMermaidTheme
};
