const HEADERS = [
  [/^(flowchart|graph)\b/, "flowchart"],
  [/^sequenceDiagram\b/, "sequence"],
  [/^classDiagram/, "class"],
  [/^stateDiagram/, "state"],
  [/^erDiagram/, "er"],
  [/^journey\b/, "journey"],
  [/^gantt\b/, "gantt"],
  [/^pie\b/, "pie"],
  [/^mindmap\b/, "mindmap"],
  [/^timeline\b/, "timeline"],
  [/^quadrantChart\b/, "quadrant"],
  [/^gitGraph\b/, "git"],
  [/^C4(Context|Container|Component|Dynamic|Deployment)\b/, "c4"],
  [/^sankey(-beta)?\b/, "sankey"],
  [/^xychart(-beta)?\b/, "xychart"],
  [/^block(-beta)?\b/, "block"],
  [/^packet(-beta)?\b/, "packet"],
  [/^kanban\b/, "kanban"],
  [/^architecture(-beta)?\b/, "architecture"],
  [/^radar(-beta)?\b/, "radar"],
  [/^requirementDiagram\b/, "requirement"],
  [/^zenuml\b/, "zenuml"]
];
function splitFrontmatter(source) {
  const lines = source.split("\n");
  let title = null;
  let bodyStartIndex = 0;
  if (lines.length > 0 && lines[0].trim() === "---") {
    bodyStartIndex = lines.length;
    for (let j = 1; j < Math.min(lines.length, 30); j++) {
      const s = lines[j].trim();
      if (s === "---") {
        bodyStartIndex = j + 1;
        break;
      }
      const m = /^title:\s*(.+)$/.exec(s);
      if (m) title = m[1].trim().replace(/^["']|["']$/g, "");
    }
  }
  return { title, bodyStartIndex, lines };
}
const DETECTABLE_DIAGRAM_TYPES = HEADERS.map(
  ([, type]) => type
);
function detectDiagramType(source) {
  const { bodyStartIndex, lines } = splitFrontmatter(source);
  for (let i = bodyStartIndex; i < lines.length; i++) {
    const s = lines[i].trim();
    if (!s || s.startsWith("%%")) continue;
    for (const [pattern, type] of HEADERS) {
      if (pattern.test(s)) return type;
    }
    return "unknown";
  }
  return "unknown";
}
function extractMermaidTitle(source) {
  return splitFrontmatter(source).title;
}
function setMermaidTitle(source, title) {
  const clean = title.trim();
  if (!clean) throw new Error("A diagram title cannot be empty.");
  if (/[\n\r]/.test(clean))
    throw new Error("A diagram title must be a single line.");
  if (/["']/.test(clean))
    throw new Error(
      "A diagram title cannot contain quote characters \u2014 mermaid frontmatter is YAML and would not read it back."
    );
  const { lines, bodyStartIndex } = splitFrontmatter(source);
  const entry = `title: ${/[:#]/.test(clean) ? `"${clean}"` : clean}`;
  if (lines.length === 0 || lines[0].trim() !== "---")
    return ["---", entry, "---", ...lines].join("\n");
  if (bodyStartIndex >= lines.length)
    throw new Error(
      "This diagram opens a `---` frontmatter block that is never closed \u2014 fix the source before setting a title."
    );
  const otherKeys = lines.slice(1, bodyStartIndex - 1).filter((line) => !/^\s*title\s*:/.test(line));
  return ["---", entry, ...otherKeys, "---", ...lines.slice(bodyStartIndex)].join(
    "\n"
  );
}
export {
  DETECTABLE_DIAGRAM_TYPES,
  detectDiagramType,
  extractMermaidTitle,
  setMermaidTitle,
  splitFrontmatter
};
